﻿import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import program from "../../../docs/research/question-topic-program-20261111.json";
import packet from "../../../docs/research/question-topic-bariatric-metabolic-20261111.json";
import ledger from "../../../docs/research/sources-question-topic-bariatric-metabolic-20261111.json";
import { PROTOTYPE_BALANCE_RELEASE } from "../../balance-config/src/prototype-balance";
import { SYNTHETIC_CLINICAL_RELEASE } from "./synthetic-content";
import { QUESTION_PROGRAM_BATCH4_ACCEPTED_QUESTIONS } from "./question-program-batch4-accepted-20261111";
import { QUESTION_NEW_N2_ROUND3_CASES, QUESTION_NEW_N2_ROUND3_QUESTIONS } from "./question-new-n2-round3-20261104";
import { answerChoiceTimingRegistryEntrySchema, syntheticClinicalCaseSchema, testedConceptSchema } from "./schema";
import {
  BARIATRIC_METABOLIC_TOPIC_ALL_ITEMS as allItems,
  BARIATRIC_METABOLIC_TOPIC_ITEMS as items,
  BARIATRIC_METABOLIC_TOPIC_PARKED_ITEMS as parkedItems,
  BARIATRIC_METABOLIC_TOPIC_CASES as cases,
  BARIATRIC_METABOLIC_TOPIC_REVIEW_PASSED_CASES as passedCases,
  BARIATRIC_METABOLIC_TOPIC_PENDING_REVIEW_CASES as pendingCases,
  BARIATRIC_METABOLIC_TOPIC_SALVAGE_CASES as salvageCases,
  BARIATRIC_METABOLIC_TOPIC_SALVAGE_QUESTIONS as salvageQuestions,
  BARIATRIC_METABOLIC_TOPIC_SALVAGE_REVIEW_QUEUE as salvageQueue,
  BARIATRIC_METABOLIC_TOPIC_QUESTIONS as questions,
  BARIATRIC_METABOLIC_TOPIC_ALL_QUESTIONS as allQuestions,
  BARIATRIC_METABOLIC_TOPIC_PARKED_QUESTIONS as parkedQuestions,
  BARIATRIC_METABOLIC_TOPIC_CONCEPTS as concepts,
  BARIATRIC_METABOLIC_TOPIC_CONCEPT_PROPOSALS as conceptProposals,
  BARIATRIC_METABOLIC_TOPIC_TIMING_PROPOSALS as timing,
  BARIATRIC_METABOLIC_TOPIC_ORDER_PROPOSALS as orders,
  BARIATRIC_METABOLIC_TOPIC_SOURCE_LINKS as links,
  BARIATRIC_METABOLIC_TOPIC_AUTHOR_GATES as gates,
  BARIATRIC_METABOLIC_TOPIC_STATEMENT_MAPPINGS as mappings,
  BARIATRIC_METABOLIC_TOPIC_COMPOSITION_PROPOSALS as compositions,
  BARIATRIC_METABOLIC_TOPIC_MANIFEST as manifest,
} from "./question-topic-bariatric-metabolic-20261111";
const digest = (value: unknown) => createHash("sha256").update(typeof value === "string" ? value : JSON.stringify(value)).digest("hex");
const sourceFile = (file: string) => new URL(`../../../${file}`, import.meta.url);
const canonical = (value: unknown): unknown => Array.isArray(value) ? value.map(canonical)
  : value && typeof value === "object" ? Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical((value as Record<string, unknown>)[key])])) : value;
const specs = allItems.flatMap(c => c.nodes);

describe("bariatric-metabolic independent-review correction", () => {
  it("retains the complete assigned legacy audit and six concept histories", () => {
    const assigned = program.inventory.filter(r => r.primaryTopicSlug === "bariatric-metabolic");
    expect(packet.audit.map(r => r.recordId).sort()).toEqual(assigned.map(r => r.recordId).sort());
    expect(packet.audit).toHaveLength(15);
    expect(packet.coverageHistory.map(c => c.conceptId).sort()).toEqual(program.concepts.filter(c => c.primaryTopicSlug === "bariatric-metabolic").map(c => c.conceptId).sort());
    expect(packet.audit.filter(a => a.verdict === "Keep")).toHaveLength(1);
    expect(packet.audit.filter(a => a.verdict === "Rewrite")).toHaveLength(3);
    expect(packet.audit.filter(a => a.verdict === "Retire-and-replace")).toHaveLength(11);
    expect(packet.audit.reduce((n, a) => n + a.distinctVisibleContextCount, 0)).toBe(15);
    expect(packet.before.reduce((n, b) => n + b.allRetainedContexts.length, 0)).toBe(17);
    for (const a of packet.audit) if (a.verdict !== "Keep")
      expect(a.proposedVariantIds.every(id => allQuestions.some(q => q.id === id))).toBe(true);
  });
  it("preserves exact assigned inputs and the held legacy PASS", () => {
    for (const input of packet.assignment.sourceHashes)
      expect(digest(readFileSync(sourceFile(input.file), "utf8")), input.file).toBe(input.currentSha256);
    for (const before of packet.before.filter(b => b.liveCase !== null)) {
      const current = SYNTHETIC_CLINICAL_RELEASE.cases.find(c => c.id === before.liveCase!.id);
      expect(digest(canonical(current)), before.recordId).toBe(digest(canonical(before.liveCase)));
    }
    const freeze = packet.assignment.frozenReferences[0]!;
    expect(digest(QUESTION_NEW_N2_ROUND3_QUESTIONS.find(q => q.id === freeze.variantId))).toBe(freeze.questionSha256);
    expect(digest(QUESTION_NEW_N2_ROUND3_CASES.find(c => c.id === "case.n2.marginal-ulcer-obstructive-escalation.v1"))).toBe(freeze.caseSha256);
    expect(packet.assignment.recordedHolds.map(h => h.id).sort()).toEqual([
      "claim.n2r3.recurrent-gj-graded-dilation", "review.n2.marginal-ulcer-obstructive-escalation.v3",
    ]);
    expect(freeze.currentAdmission).toBe("source-held, not accepted");
    expect(allQuestions.some(q => q.id === freeze.variantId)).toBe(false);
  });
  it("binds every review decision to exactly one preserved item or one v2 attempt", () => {
    expect(digest(readFileSync(sourceFile(packet.reviewRound2.reviewPath), "utf8"))).toBe(packet.reviewRound2.reviewSha256);
    expect(packet.reviewRound2.decisions).toHaveLength(18);
    expect(new Set(packet.proposals.map(p => p.reviewedVariantId)).size).toBe(18);
    expect(packet.proposals.filter(p => p.status === "pass-preserved")).toHaveLength(3);
    expect(packet.proposals.filter(p => p.status === "revised")).toHaveLength(8);
    expect(packet.proposals.filter(p => p.status === "salvage")).toHaveLength(3);
    expect(packet.proposals.filter(p => p.status === "parked")).toHaveLength(4);
    for (const d of packet.reviewRound2.decisions) {
      const p = packet.salvage.baselineProposals.find(p => p.reviewedVariantId === d.id)!;
      expect(p).toBeDefined();
      expect(p.revisionAttempts).toBe(d.verdict === "PASS" ? 0 : 1);
      expect(p.question.id).toBe(d.verdict === "PASS" ? d.id : d.id.replace(/\.v1$/, ".v2"));
      if (d.verdict === "PASS") expect(p.status).toBe("pass-preserved");
      else for (const text of Object.values(p.issueResponses)) expect(text.length).toBeGreaterThan(20);
      expect(p.before[0]!.questionSha256).toBe(digest(packet.reviewRound2.baselineProposals.find(b => b.question.id === d.id)!.question));
    }
  });
  it("keeps all three PASS questions, scored nodes and patient/profile fields exact", () => {
    for (const frozen of packet.reviewRound2.passPreservation) {
      const q = questions.find(q => q.id === frozen.variantId)!;
      const c = cases.find(c => c.decisionNodes.some(n => n.id === frozen.nodeId))!;
      const n = c.decisionNodes.find(n => n.id === frozen.nodeId)!;
      expect(q).toEqual(frozen.question);
      expect(n).toEqual(frozen.node);
      expect(digest(q)).toBe(frozen.questionSha256);
      expect(digest(n)).toBe(frozen.nodeSha256);
      for (const [field, value] of Object.entries(frozen.caseHeader))
        expect((c as unknown as Record<string, unknown>)[field], field).toEqual(value);
    }
    const pairId = "case.topic.bariatric-metabolic.persistent-pain-after-rygb.v1";
    expect(cases.find(c => c.id === pairId)).toEqual(packet.reviewRound2.baselineCases.find(c => c.id === pairId));
  });
  it("splits the passing source-control companion and admits no mixed or pending sequence", () => {
    expect(passedCases).toHaveLength(2);
    expect(passedCases.flatMap(c => c.decisionNodes)).toHaveLength(3);
    expect(pendingCases).toHaveLength(8);
    const split = passedCases.find(c => c.id.includes("pass-preserved"))!;
    expect(split.decisionNodes.map(n => n.questionVariantId)).toEqual(["question.topic.bariatric-metabolic.deterioration-source-control.v1"]);
    expect(split.decisionNodes[0]!.currentUpdate).toContain("CT showed");
    for (const c of allItems) expect(new Set(c.nodes.map(n => n.disposition)).size).toBe(1);
    for (const c of compositions) {
      expect(c.integrationEligible).toBe(false);
      expect(c.pipelinePassed).toBe(false);
      expect(c.allScoredNodesIndependentlyPassed).toBe(c.nodeStatuses.every(n => n.status === "pass-preserved" || n.status === "salvage"));
      if (c.selectionState === "salvage_pending_context_review") {
        expect(c.editorialReviewEligible).toBe(false);
        expect(salvageCases.some(p => p.id === c.caseId)).toBe(true);
      } else if (c.allScoredNodesIndependentlyPassed) expect(passedCases.some(p => p.id === c.caseId)).toBe(true);
      else expect(c.editorialReviewEligible).toBe(false);
    }
  });
  it("excludes four parked attempts and leaves the disputed vitamin A route unkeyed", () => {
    expect(parkedItems).toHaveLength(4);
    expect(parkedQuestions).toHaveLength(4);
    for (const n of parkedItems.flatMap(c => c.nodes)) {
      expect(n.parkReason!.length).toBeGreaterThan(100);
      expect(questions.some(q => q.id.endsWith(`${n.slug}.v2`))).toBe(false);
      expect(cases.some(c => c.decisionNodes.some(q => q.questionVariantId.endsWith(`${n.slug}.v2`)))).toBe(false);
    }
    const vision = parkedQuestions.find(q => q.id.includes("fat-malabsorption"))!;
    expect(vision.answerChoices.some(a => a.isCorrect)).toBe(false);
    expect(packet.ownerApprovalsNeeded.some(a => a.id === "owner.bariatric-metabolic.vitamin-a-route-unkeyed")).toBe(true);
  });
  it("normalizes thirteen clinic review cases with consistent finite profiles and no hospital capability", () => {
    expect(cases).toHaveLength(13);
    expect(questions).toHaveLength(14);
    for (const c of cases) {
      const spec = items.find(i => i.id === c.id)!;
      expect(syntheticClinicalCaseSchema.parse(c)).toEqual(c);
      expect(c.requiredClinicalSetting).toBe("clinic");
      expect(c.earliestFacilityStage).toBe(0);
      expect(c.requiredCapabilityIds).toEqual([]);
      expect(c.decisionNodes.length).toBeLessThanOrEqual(3);
      expect(c.patientDisplayName).toBe(spec.patientName);
      expect(c.presentation).toContain(`${spec.age}-year-old`);
      expect(c.prototypeDemographics!.sexLabel).toBe(spec.sex);
      expect(c.chiefComplaint!.split(/\s+/).length).toBeLessThanOrEqual(5);
      expect(c.approvedInstantiationProfiles).toHaveLength(1);
      expect(c.approvedInstantiationProfiles![0]!.presentation).toBe(c.presentation);
      for (const n of c.decisionNodes) expect(n.stem).toContain("{patientName}");
    }
  });
  it("uses exact versioned option identities, one key and runtime shuffling", () => {
    expect(new Set(allQuestions.map(q => q.id)).size).toBe(18);
    expect(new Set(cases.map(c => c.id)).size).toBe(cases.length);
    for (const c of cases) for (const n of c.decisionNodes) {
      expect(n.shuffleAnswers).toBe(true);
      expect(n.answerChoices.length).toBeGreaterThanOrEqual(3);
      expect(n.answerChoices.length).toBeLessThanOrEqual(4);
      expect(n.answerChoices.filter(a => a.isCorrect)).toHaveLength(1);
      expect(new Set(n.answerChoices.map(a => a.id)).size).toBe(n.answerChoices.length);
      if (n.questionVariantId.endsWith(".v2")) expect(n.answerChoices.every(a => a.id.includes(".v2."))).toBe(true);
    }
    expect(manifest.reviewOrderLabel).toBe("key shown first for review only.");
  });
  it("preserves unchanged concepts and separates five newly changed meanings", () => {
    for (const c of concepts) expect(testedConceptSchema.parse(c)).toEqual(c);
    const changedThisRound = specs.filter(n => (n.disposition === "revised" || n.disposition === "salvage") && packet.reviewRound2.baselineProposals.find(b => b.question.id === n.reviewedQuestionId)!.question.conceptId !== n.conceptId);
    expect(changedThisRound).toHaveLength(5);
    for (const n of changedThisRound) {
      expect(n.conceptRelation).toBe("new_version");
      expect(n.previousConceptId).toBe(packet.reviewRound2.baselineProposals.find(b => b.question.id === n.reviewedQuestionId)!.question.conceptId);
      expect(n.conceptId).not.toBe(n.previousConceptId);
    }
    expect(conceptProposals.every(c => c.historyPolicy.includes("No transfer"))).toBe(true);
  });
  it("provides atomic support for each current question and option, including parked audit claims", () => {
    const claims = new Map(ledger.claims.map(c => [c.id, c]));
    const sources = new Set(ledger.sources.map(s => s.id));
    expect(mappings).toHaveLength(18);
    for (const q of allQuestions) {
      const mapping = mappings.find(m => m.questionVariantId === q.id)!;
      expect(mapping.choiceMappings.map(c => c.choiceId)).toEqual(q.answerChoices.map(a => a.id));
      for (const id of q.supportingEvidenceClaimIds) expect(claims.has(id), id).toBe(true);
      for (const a of mapping.choiceMappings) {
        for (const id of a.evidenceClaimIds) expect(claims.has(id), id).toBe(true);
        for (const text of [a.rationale, a.temptation, a.correctUnder]) expect(text.length).toBeGreaterThan(25);
      }
    }
    for (const c of ledger.claims) {
      expect(c.limitation.length).toBeGreaterThan(20);
      for (const id of c.sourceIds) expect(sources.has(id), id).toBe(true);
    }
    for (const s of ledger.sources) expect([...s.evidenceClaimIds].sort()).toEqual(ledger.claims.filter(c => c.sourceIds.includes(s.id)).map(c => c.id).sort());
  });
  it("maps every testing alternative to the exact label and an existing timing profile", () => {
    expect(timing).toHaveLength(14);
    const profiles = new Set(PROTOTYPE_BALANCE_RELEASE.answerChoiceTimingProfiles.map(p => p.id));
    const tests = specs.filter(n => n.disposition !== "parked" && n.choices.some(a => a.timingProfileId));
    expect(tests).toHaveLength(6);
    for (const t of timing) {
      answerChoiceTimingRegistryEntrySchema.parse(t);
      const n = cases.flatMap(c => c.decisionNodes).find(n => n.id === t.nodeId)!;
      const spec = specs.find(s => t.questionVariantId === `question.topic.bariatric-metabolic.${s.slug}.v${s.version}`)!;
      if (spec.choices.some(a => a.timingProfileId)) {
        expect(t.classification.kind).toBe("test_choices");
        if (t.classification.kind === "test_choices") {
          expect(t.classification.choices.map(a => [a.choiceId, a.choiceLabel])).toEqual(n.answerChoices.map(a => [a.id, a.label]));
          for (const a of t.classification.choices) {
            expect(a.timing.kind).toBe("test");
            if (a.timing.kind === "test") expect(profiles.has(a.timing.timingProfileId)).toBe(true);
          }
        }
      } else expect(t.classification.kind).toBe("no_test");
    }
    for (const c of cases) for (const n of c.decisionNodes) {
      expect(n.resultGateAfter).toBeNull();
      expect(n.answerChoices.every(a => a.serviceRequest === null)).toBe(true);
    }
    expect(orders.every(o => o.newExecutableServiceRequested === false)).toBe(true);
  });
  it("records concrete gates and explicitly bounded moderate exceptions without claiming re-review PASS", () => {
    expect(gates).toHaveLength(18);
    expect(gates.filter(g => g.reasoningMode === "focused_moderate_exception")).toHaveLength(2);
    for (const g of gates) {
      expect(g.gateRole).toBe("manual_author_self_check");
      expect(g.independentPass).toBe(false);
      expect(g.clinicalApproval).toBe(false);
      expect(g.coverTheKey.length).toBeGreaterThan(80);
      if (g.disposition === "parked") expect(g.parkedReason!.length).toBeGreaterThan(100);
      else {
        expect(g.singleBestAnswer!.decidingObservation.length).toBeGreaterThan(35);
        expect(g.singleBestAnswer!.counterfactual.length).toBeGreaterThan(35);
        if (g.reasoningMode === "two_step") expect(g.twoConsequentialSteps).toHaveLength(2);
        else { expect(g.twoConsequentialSteps).toEqual([]); expect(g.focusedModerateScope!.authority).toContain("Manager review instruction"); }
      }
    }
  });
  it("keeps all clinical records unapproved and source rights separate from authority", () => {
    expect(ledger.sources).toHaveLength(10);
    expect(ledger.claims).toHaveLength(52);
    for (const r of [...allQuestions, ...conceptProposals, ...ledger.sources, ...ledger.claims]) {
      expect(r.reviewStatus).toBe("needs_clinician_review");
      expect(r.lastClinicianReview).toBeNull();
      expect(r.aiAssistedDrafting).toBe(true);
    }
    for (const s of ledger.sources) {
      expect(s.completeCitation.length).toBeGreaterThan(80);
      expect(s.authors.length).toBeGreaterThan(0);
      expect(s.authorityAssessment.length).toBeGreaterThan(40);
      expect(s.reuseNotes.length).toBeGreaterThan(40);
      expect(new URL(s.officialUrl).protocol).toBe("https:");
    }
    for (const l of links) expect([l.target, l.rel, l.referrerPolicy]).toEqual(["_blank", "noopener noreferrer", "no-referrer"]);
    expect(manifest.pipelinePassed).toBe(false);
    expect(manifest.publicReleaseAuthorized).toBe(false);
    expect(manifest.liveManifestEdited).toBe(false);
  });
  it("reconciles the packet, exact before references and evidence ledger", () => {
    expect(packet.authoredCases).toEqual(cases);
    expect(packet.proposals.map(p => p.question)).toEqual(allQuestions);
    expect(packet.conceptProposals).toEqual(conceptProposals);
    expect(packet.compositionProposals).toEqual(compositions);
    for (const p of packet.proposals) {
      expect(p.statementMappings).toEqual(mappings.find(m => m.questionVariantId === p.question.id));
      expect(p.manualAuthorGate).toEqual(gates.find(g => g.questionVariantId === p.question.id));
      expect(ledger.questionClaimMappings.some(m => m.questionVariantId === p.question.id)).toBe(true);
      if (p.status !== "parked") expect(p.keyFirstReviewChoices[0]!.isCorrect).toBe(true);
      expect(p.supplyEligible).toBe(false);
    }
    expect(ledger.round1QuestionClaimMappings).toHaveLength(18);
  });
  it("recognizes batch-4 acceptance while keeping every unaccepted candidate out of the default release", () => {
    const admitted = new Set(SYNTHETIC_CLINICAL_RELEASE.cases.flatMap(c => c.decisionNodes.map(n => n.questionVariantId)));
    expect(allQuestions.filter(q => admitted.has(q.id)).map(q => q.id).sort()).toEqual(packet.salvage.acceptedPreservation.map(p => p.questionVariantId).sort());
    expect(salvageQuestions.some(q => admitted.has(q.id))).toBe(false);
    expect(parkedQuestions.some(q => admitted.has(q.id))).toBe(false);
  });
  it("queues exactly the three skipped PASS identities and no accepted or non-PASS companion", () => {
    const dispositions = JSON.parse(readFileSync(sourceFile(packet.salvage.dispositionsPath), "utf8")) as {
      items: Array<{ topic: string; nodeId: string; status: string; evidence: { record: { verdict: string } } }>;
    };
    expect(digest(readFileSync(sourceFile(packet.salvage.dispositionsPath), "utf8"))).toBe(packet.salvage.dispositionsSha256);
    expect(digest(readFileSync(sourceFile(packet.salvage.reviewPath), "utf8"))).toBe(packet.salvage.reviewSha256);
    const skipped = dispositions.items.filter(i => i.topic === "bariatric-metabolic" && i.status === "skipped" && i.evidence.record.verdict === "PASS");
    expect(salvageQueue.map(i => i.nodeId).sort()).toEqual(skipped.map(i => i.nodeId).sort());
    expect(salvageCases).toHaveLength(3);
    expect(salvageQuestions).toHaveLength(3);
    for (const i of salvageQueue) {
      expect(i.status).toBe("salvage");
      expect(packet.proposals.find(p => p.question.id === i.questionVariantId)!.status).toBe("salvage");
      expect(packet.salvage.acceptedPreservation.some(p => p.nodeId === i.nodeId)).toBe(false);
    }
  });
  it("preserves each salvage PASS question and every scored field with only necessary terminal metadata", () => {
    const withoutTerminal = (value: unknown) => {
      const copy = JSON.parse(JSON.stringify(value)) as Record<string, unknown>;
      delete copy.terminalDispositions;
      return copy;
    };
    for (const item of packet.salvage.items) {
      expect(item.review.verdict).toBe("PASS");
      const q = salvageQuestions.find(q => q.id === item.questionVariantId)!;
      const node = salvageCases.find(c => c.id === item.caseId)!.decisionNodes[0]!;
      expect(q).toEqual(item.beforeQuestion);
      expect(digest(q)).toBe(item.beforeQuestionSha256);
      expect(withoutTerminal(node)).toEqual(withoutTerminal(item.beforeNode));
      if (item.beforeNode.terminalDispositions.length) expect(digest(node)).toBe(item.beforeNodeSha256);
      else {
        expect(item.schemaMetadataAdded).toHaveLength(1);
        expect(node.terminalDispositions.map(d => d.answerChoiceId).sort()).toEqual(node.answerChoices.filter(a => !a.isCorrect).map(a => a.id).sort());
        for (const d of node.terminalDispositions) {
          expect(d.kind).toBe("no_terminal_outcome");
          if (d.kind === "no_terminal_outcome") expect(d.clinicalRationale).toBe(node.answerChoices.find(a => a.id === d.answerChoiceId)!.rationale);
        }
      }
    }
  });
  it("makes every salvage case independently complete with one neutral presentation addition", () => {
    const nodeIds = cases.flatMap(c => c.decisionNodes.map(n => n.id));
    expect(new Set(nodeIds).size).toBe(14);
    for (const item of packet.salvage.items) {
      const c = salvageCases.find(c => c.id === item.caseId)!;
      expect(c.decisionNodes.map(n => n.id)).toEqual([item.nodeId]);
      expect(c.presentation).toBe(item.beforeCase.presentation + " You review her prior bariatric clinic records.");
      expect(c.patientDisplayName).toBe(item.beforeCase.patientDisplayName);
      expect(c.prototypeDemographics).toEqual(item.beforeCase.prototypeDemographics);
      expect(c.chiefComplaint).toBe(item.beforeCase.chiefComplaint);
      expect(c.approvedInstantiationProfiles![0]!.presentation).toBe(c.presentation);
      expect(c.learningSummary).toBe(c.decisionNodes[0]!.explanation);
      expect(c.decisionNodes[0]!.resultGateAfter).toBeNull();
      expect(c.requiredClinicalSetting).toBe("clinic");
      expect(packet.salvage.reviewQueue.some(q => q.caseId === c.id)).toBe(true);
    }
  });
  it("preserves all three accepted questions, nodes and both accepted cases exactly", () => {
    for (const frozen of packet.salvage.acceptedPreservation) {
      const c = SYNTHETIC_CLINICAL_RELEASE.cases.find(c => c.id === frozen.caseId)!;
      const n = c.decisionNodes.find(n => n.id === frozen.nodeId)!;
      const q = QUESTION_PROGRAM_BATCH4_ACCEPTED_QUESTIONS.find(q => q.id === frozen.questionVariantId)!;
      expect(digest(c)).toBe(frozen.runtimeCaseSha256);
      expect(digest(n)).toBe(frozen.runtimeNodeSha256);
      expect(digest(q)).toBe(frozen.runtimeQuestionSha256);
      expect(digest(cases.find(c => c.id === frozen.caseId))).toBe(frozen.ownedCaseSha256);
      expect(digest(questions.find(q => q.id === frozen.questionVariantId))).toBe(frozen.ownedQuestionSha256);
    }
  });
  it("rebinds salvage timing and claims by case while preserving exact choice bindings and source dates", () => {
    expect(ledger.salvage.newSourceCount).toBe(0);
    expect(ledger.salvage.newClaimCount).toBe(0);
    for (const item of packet.salvage.items) {
      const old = packet.salvage.baselineProposals.find(p => p.question.id === item.questionVariantId)!;
      const t = timing.find(t => t.questionVariantId === item.questionVariantId)!;
      expect(t.caseId).toBe(item.caseId);
      expect(t.classification).toEqual(old.timing!.classification);
      const map = ledger.questionClaimMappings.find(m => m.questionVariantId === item.questionVariantId)!;
      expect(map.caseId).toBe(item.caseId);
      expect(map.disposition).toBe("salvage");
      expect(map.evidenceClaimIds).toEqual(old.statementMappings.evidenceClaimIds);
      expect(map.choiceMappings).toEqual(old.statementMappings.choiceMappings);
    }
  });
});
